const payload = $input.first()?.json || {};
const issue = payload.issue || {};

const issue_key = String(issue.key || '')
  .trim()
  .toUpperCase();

const issue_id = String(issue.id || '');

if (!issue_key) {
  throw new Error('DELETED_JIRA_ISSUE_KEY_MISSING');
}

const project_key = String(
  issue.fields?.project?.key ||
  issue_key.split('-')[0] ||
  ''
)
  .trim()
  .toUpperCase();

const eventTimestamp = Number(payload.timestamp);

const deleted_at = Number.isFinite(eventTimestamp)
  ? new Date(eventTimestamp).toISOString()
  : new Date().toISOString();

return [{
  json: {
    issue_key,
    issue_id,
    project_key,
    event_type:
      payload.webhookEvent || 'jira:issue_deleted',
    deleted_at,
    storage_prefix: `JIRA/${issue_key}`,
  }
}];

const context = $('Build Delete Context').first().json;
const prefix = context.storage_prefix;

const objects = [];

for (const item of $input.all()) {
  const value = item.json;

  if (Array.isArray(value)) {
    objects.push(...value);
  } else if (Array.isArray(value?.data)) {
    objects.push(...value.data);
  } else if (value?.name) {
    objects.push(value);
  }
}

const storage_paths = [...new Set(
  objects
    .filter((object) => object?.name && object?.id)
    .map((object) => {
      const name = String(object.name);

      return name.startsWith(prefix + '/')
        ? name
        : `${prefix}/${name}`;
    })
)]
  .sort((a, b) => a.localeCompare(b));

return [{
  json: {
    ...context,
    storage_paths,
    has_storage: storage_paths.length > 0,
    storage_object_count: storage_paths.length,
  }
}];

const context = $('Build Delete Context').first().json;

return [{
  json: {
    ok: true,
    mode: 'skipped_deleted_non_ssd_issue',
    issue_key: context.issue_key,
    issue_id: context.issue_id,
    project_key: context.project_key,
    event_type: context.event_type,
    finished_at: new Date().toISOString(),
  }
}];

const crypto = require('crypto');

const FLOW_VERSION = 'jira-rag-v4';

function toText(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  try { return JSON.stringify(value); } catch { return String(value); }
}

function extractText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(extractText).join('');
  if (node.type === 'text') return node.text || '';
  if (node.type === 'hardBreak') return '\n';
  if (node.type === 'mention') return node.attrs?.text || node.attrs?.id || '';
  if (node.type === 'inlineCard') return node.attrs?.url || '';
  if (node.type === 'emoji') return node.attrs?.text || node.attrs?.shortName || '';
  if (node.type === 'status') return node.attrs?.text || '';
  if (node.type === 'date') return node.attrs?.timestamp || '';
  const content = extractText(node.content || []);
  if (node.type === 'paragraph' || node.type === 'heading') return content + '\n';
  if (node.type === 'listItem') return '- ' + content.trimEnd() + '\n';
  if (node.type === 'bulletList' || node.type === 'orderedList' || node.type === 'blockquote' || node.type === 'codeBlock') return content + '\n';
  return content;
}

function normalizeText(value) {
  let text = typeof value === 'string' ? value : extractText(value);
  return text
    .replace(/\{code(?::[^}]*)?\}([\s\S]*?)\{code\}/gi, '$1')
    .replace(/\{noformat\}([\s\S]*?)\{noformat\}/gi, '$1')
    .replace(/\{color[^}]*\}(.*?)\{color\}/gi, '$1')
    .replace(/!([^|!]+)(?:\|[^!]*)?!/g, '[Bild: $1]')
    .replace(/\[([^|\]]+)\|([^\]]+)\]/g, '$1 ($2)')
    .replace(/\[~([^\]]+)\]/g, '@$1')
    .replace(/<\/?[^>]+(>|$)/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

function extractMentionedIssueKeys(value) {
  const found = toText(value).match(/\b[A-Z][A-Z0-9_]*-\d+\b/g) || [];
  return [...new Set(found)];
}

function stableStrings(values) {
  return [...new Set((values || []).filter(Boolean).map((value) => String(value)))].sort((a, b) => a.localeCompare(b));
}

const issue = $('Get Issue').first().json || {};
const fields = issue.fields || {};
const commentItems = $('Get Comments').all();

const issue_key = String(issue.key || '').trim().toUpperCase();
const issue_id = String(issue.id || '');

if (!issue_key) {
  throw new Error('JIRA_ISSUE_KEY_MISSING');
}

const summary = normalizeText(fields.summary || '');
const description = normalizeText(fields.description || '');

// ============================================================
// KOMMENTARE: NACH SICHTBARKEIT GETRENNT, NICHT VERWORFEN
//
// jsdPublic === true  -> comments          -> audience des Tickets
// jsdPublic !== true  -> internal_comments -> audience it_internal
//
// Interner Support-Verlauf ist wertvolles Wissen, gehoert aber
// ausschliesslich der IT. Er wird deshalb eingebettet, jedoch mit
// eigener audience.
//
// FAIL CLOSED: Liefert die Jira-API das Feld jsdPublic ueberhaupt
// nicht, ist die Sichtbarkeit unbekannt. Dann gelten ALLE Kommentare
// als intern. Frueher galten sie in diesem Fall als oeffentlich -
// das war die falsche Richtung.
// ============================================================

const commentsRaw = commentItems
  .map((item) => item.json || {})
  .filter((comment) => Object.keys(comment).length > 0);

const jsd_flag_available = commentsRaw.some((comment) =>
  Object.prototype.hasOwnProperty.call(comment, 'jsdPublic')
);

const publicCommentsRaw = jsd_flag_available
  ? commentsRaw.filter((comment) => comment.jsdPublic === true)
  : [];

const internalCommentsRaw = jsd_flag_available
  ? commentsRaw.filter((comment) => comment.jsdPublic !== true)
  : commentsRaw;

const internal_comment_count = internalCommentsRaw.length;

function mapComment(comment, isInternal) {
  return {
    id: comment.id ? String(comment.id) : null,
    created_at: comment.created || null,
    updated_at: comment.updated || null,
    author_name: comment.author?.displayName || null,
    author_email: comment.author?.emailAddress || null,
    body: normalizeText(comment.body),
    is_internal: isInternal,
  };
}

function sortComments(list) {
  return list.sort((a, b) => {
    const byCreated = String(a.created_at || '').localeCompare(String(b.created_at || ''));
    if (byCreated !== 0) return byCreated;
    return String(a.id || '').localeCompare(String(b.id || ''));
  });
}

const comments = sortComments(
  publicCommentsRaw.map((c) => mapComment(c, false)).filter((c) => c.body)
);

const internal_comments = sortComments(
  internalCommentsRaw.map((c) => mapComment(c, true)).filter((c) => c.body)
);

// Erwaehnte Tickets nur aus oeffentlichen Quellen ableiten - der Header-Chunk
// ist oeffentlich und darf keine internen Verweise transportieren.
let mentioned_issue_keys = [];
mentioned_issue_keys.push(...extractMentionedIssueKeys(fields.description));
for (const comment of publicCommentsRaw) {
  mentioned_issue_keys.push(...extractMentionedIssueKeys(comment.body));
}
mentioned_issue_keys = [...new Set(mentioned_issue_keys)]
  .filter((key) => key !== issue_key)
  .sort((a, b) => a.localeCompare(b));

const linked_tickets = (fields.issuelinks || [])
  .map((link) => ({
    key: link.outwardIssue?.key || link.inwardIssue?.key || null,
    type: link.type?.outward || link.type?.inward || 'relates to',
  }))
  .filter((link) => link.key)
  .sort((a, b) => `${a.key}|${a.type}`.localeCompare(`${b.key}|${b.type}`));

const attachments = (Array.isArray(fields.attachment) ? fields.attachment : [])
  .map((attachment) => ({
    id: attachment.id ? String(attachment.id) : null,
    filename: attachment.filename || null,
    mime_type: attachment.mimeType || null,
    size: attachment.size ?? null,
    content_url: attachment.content || null,
    thumbnail_url: attachment.thumbnail || null,
  }))
  .sort((a, b) => String(a.id || a.filename || '').localeCompare(String(b.id || b.filename || '')));

// ============================================================
// BILDAUSWAHL: NUR RASTERFORMATE
//
// FIX 08/2026 (Beleg: Lauf 103489, SSD-8686, Footer E-Rechnung.svg):
// Die alte Pruefung liess jedes mime image/* durch. image/svg+xml erfuellt
// das, GraphicsMagick im n8n-Container hat dafuer aber kein Decode-Delegate.
// Resize Standard JPEG brach mit "gm identify: No decode delegate" ab und
// riss den kompletten Ingest-Lauf mit - inklusive der Cleanup-Kette hinter
// der Bildschleife. Es wird deshalb auf eine Whitelist rasterbarer Formate
// umgestellt. Nicht rasterbare Anhaenge bleiben in attachments und damit im
// Header-Chunk sichtbar, sie werden nur nicht mehr durch die Bildstrecke
// geschickt.
// ============================================================
const RASTER_MIMES = [
  'image/png',
  'image/jpeg',
  'image/jpg',
  'image/pjpeg',
  'image/gif',
  'image/bmp',
  'image/x-ms-bmp',
  'image/tiff',
  'image/webp',
];

const RASTER_EXT = /\.(png|jpe?g|gif|bmp|webp|tiff?)$/i;

function istRasterbar(attachment) {
  const mime = String(attachment.mime_type || '')
    .toLowerCase()
    .split(';')[0]
    .trim();
  const filename = String(attachment.filename || '');

  if (mime === 'image/svg+xml' || /\.svgz?$/i.test(filename)) return false;
  if (RASTER_MIMES.includes(mime)) return true;

  // Unbekanntes oder generisches mime: Endung entscheidet.
  return RASTER_EXT.test(filename);
}

const bilder = attachments
  .filter(istRasterbar)
  .filter((attachment) => attachment.content_url)
  .map((attachment, index) => ({
    attachment_id: String(attachment.id || index),
    filename: attachment.filename || `jira_image_${attachment.id || index}`,
    mime_type: attachment.mime_type || null,
    download_url: attachment.content_url,
    thumbnail_url: attachment.thumbnail_url || null,
    size: attachment.size ?? null,
  }));

const status = fields.status?.name || '';
const resolution = fields.resolution?.name || null;
const priority = fields.priority?.name || null;
const project_key = fields.project?.key || null;
const issue_type = fields.issuetype?.name || null;

const request_type =
  fields.customfield_10010?.requestType?.name ||
  fields.customfield_10010?.requestType?.defaultName ||
  null;

const created_at = fields.created || null;
const updated_at = fields.updated || null;
const due_date = fields.duedate || null;
const jira_resolved_at = fields.resolutiondate || null;
const parent_key = fields.parent?.key || null;
const epic_link = fields.customfield_10014 || fields.epic?.key || null;

const assignee_name = fields.assignee?.displayName || null;
const assignee_email = fields.assignee?.emailAddress || null;
const reporter_name = fields.reporter?.displayName || null;
const reporter_email = fields.reporter?.emailAddress || null;

const labels = stableStrings(fields.labels);
const components = stableStrings((fields.components || []).map((component) => component.name));
const fix_versions = stableStrings((fields.fixVersions || []).map((version) => version.name));

const story_points_raw =
  fields.customfield_10016 ?? fields.customfield_10028 ?? fields.story_points ?? null;

const story_points =
  story_points_raw === null || story_points_raw === undefined || story_points_raw === ''
    ? null
    : Number(story_points_raw);

let sprint = null;
const sprintCandidate = fields.customfield_10020 || fields.sprint || null;
if (Array.isArray(sprintCandidate) && sprintCandidate.length > 0) {
  sprint = sprintCandidate[sprintCandidate.length - 1]?.name || null;
} else if (typeof sprintCandidate === 'object' && sprintCandidate?.name) {
  sprint = sprintCandidate.name;
} else if (typeof sprintCandidate === 'string') {
  sprint = sprintCandidate;
}

const agent_url = fields.customfield_10010?._links?.agent || null;
const portal_url = fields.customfield_10010?._links?.web || null;
const kategorie = request_type || issue_type || project_key;

// content_hash ueber summary + description + ALLE Kommentare, damit auch eine
// Aenderung an einem internen Kommentar eine Neu-Einbettung ausloest.
const hash_source = JSON.stringify({
  summary,
  description,
  comments: [...comments, ...internal_comments].map((comment) => ({
    id: comment.id,
    created_at: comment.created_at,
    updated_at: comment.updated_at,
    author_name: comment.author_name,
    is_internal: comment.is_internal,
    body: comment.body,
  })),
});

const content_hash = crypto.createHash('sha256').update(hash_source, 'utf8').digest('hex');

// Beim Backfill-Einstieg ist der Trigger-Knoten nicht gelaufen. Ein Cross-Branch-Zugriff
// darauf bricht die Ausfuehrung ab, deshalb abgesichert lesen.
let rohEreignis = {};
try { rohEreignis = $('Jira Trigger').first().json ?? {}; } catch (e) { rohEreignis = {}; }
const ereignisTyp =
  $('Basisparameter').first().json.event_type ||
  rohEreignis.webhookEvent ||
  'unknown';

return [{
  json: {
    flow_version: FLOW_VERSION,
    issue_key,
    issue_id,
    summary,
    description,
    status,
    resolution,
    priority,
    project_key,
    issue_type,
    request_type,
    created_at,
    updated_at,
    due_date,
    jira_resolved_at,
    parent_key,
    epic_link,
    assignee_name,
    assignee_email,
    reporter_name,
    reporter_email,
    labels,
    components,
    fix_versions,
    sprint,
    story_points: Number.isFinite(story_points) ? story_points : null,
    agent_url,
    portal_url,
    kategorie,
    mentioned_issue_keys,
    linked_tickets,
    comments,
    internal_comments,
    attachments,
    bilder,
    has_images: bilder.length > 0,
    image_count: bilder.length,
    jsd_flag_available,
    internal_comment_count,
    content_hash,
    event_type: ereignisTyp,
    raw_payload: rohEreignis,
    normalized_at: new Date().toISOString(),
  }
}];

const n = $('Normalize Issue').first().json;
const candidate = $input.first()?.json || {};

const existing =
  candidate &&
  typeof candidate === 'object' &&
  !Array.isArray(candidate) &&
  candidate.ticket_key
    ? candidate
    : null;

function timestamp(value) {
  const parsed = Date.parse(value || '');
  return Number.isFinite(parsed) ? parsed : null;
}

const incomingTs = timestamp(n.updated_at);
const existingTs = timestamp(existing?.jira_updated_at);

const stale_event =
  existingTs !== null &&
  incomingTs !== null &&
  existingTs > incomingTs;

return [{
  json: {
    accept_event: !stale_event,
    stale_event,
    existing_ticket: existing || {},
    incoming_updated_at: n.updated_at,
    existing_updated_at: existing?.jira_updated_at || null,
  }
}];

const n = $('Normalize Issue').first().json;
const row = $input.first()?.json || {};

function timestamp(value) {
  const parsed = Date.parse(value || '');
  return Number.isFinite(parsed) ? parsed : null;
}

const incomingTs = timestamp(n.updated_at);
const currentTs = timestamp(row.jira_updated_at);

const current =
  incomingTs !== null &&
  currentTs !== null &&
  incomingTs === currentTs;

return [{
  json: {
    current,
    current_ticket: row,
    incoming_updated_at: n.updated_at,
    current_updated_at: row.jira_updated_at || null,
  }
}];

const CHUNK_SIZE = 1800;
const OVERLAP = 200;
const FLOW_VERSION = 'jira-rag-v4';
const NOISE_FILTER = 'v1';
const MIN_SUBSTANZ = 40;
const ALLOWED_CHUNK_TYPES = ['header', 'content', 'comment', 'solution', 'image_attachment'];
const JIRA_BASE = 'https://rwg-r.atlassian.net';

const AGENT_AUTHORS = ['rwg.automate', 'rwg automate', 'rwg_automate'];
const AGENT_BODY_MARKERS = [
  '[rwg-jira-agent',
  'automatisch durch den rwg it-assistenten generiert',
  'agenten-ersteinschaetzung',
  'dein rwg assistent',
];

const row = $('Get Ticket Row').first().json;
const n = $('Normalize Issue').first().json;

if (!row?.id) {
  throw new Error('MISSING_JIRA_TICKET_SOURCE_ID');
}

const AUDIENCE =
  typeof row.audience === 'string' && row.audience.trim() ? row.audience.trim() : null;

if (!AUDIENCE) {
  throw new Error('MISSING_TICKET_AUDIENCE: ' + n.issue_key);
}

// Interner Verlauf ist immer it_internal, unabhaengig von der Ticket-Audience.
function audienceFuer(istIntern) {
  return istIntern ? 'it_internal' : AUDIENCE;
}

function isAgentComment(comment) {
  const author = String(comment.author_name || '').toLowerCase();
  const email = String(comment.author_email || '').toLowerCase();
  const body = String(comment.body || '').toLowerCase();
  if (AGENT_AUTHORS.some((a) => author.includes(a) || email.includes(a))) return true;
  if (body.includes('agenten-erstein')) return true;
  return AGENT_BODY_MARKERS.some((m) => body.includes(m));
}

// ============================================================
// RAUSCHFILTER
// Jira-Tickets entstehen zu grossen Teilen aus E-Mails. Damit landen
// Signaturen, Rechtsfusszeilen, Safelinks-Blobs und Zitatverlaeufe in der
// Wissensbasis und verdraengen echte Inhalte aus den Suchtreffern.
// Alles, was hier entfernt wird, traegt keine fachliche Information.
// ============================================================
const ABBINDER = /(^|\n)[ \t]*(mit freundlichen gr(u|ue|\u00fc)(ss|\u00df)en|viele gr(u|ue|\u00fc)(ss|\u00df)e|beste gr(u|ue|\u00fc)(ss|\u00df)e|liebe gr(u|ue|\u00fc)(ss|\u00df)e|freundliche gr(u|ue|\u00fc)(ss|\u00df)e|danke und gr(u|ue|\u00fc)(ss|\u00df)e|sch(o|oe|\u00f6)ne gr(u|ue|\u00fc)(ss|\u00df)e|mfg|vg)\b[\s\S]*$/i;

const AUTOREPLY = /(automatic reply|automatische antwort|abwesenheitsnotiz|out of office|bin ich nicht im haus|ihre mail wird nicht weitergeleitet)/i;

function bereinige(text) {
  let t = String(text || '');
  t = t.replace(/Sie erhalten nicht h(a|ae|\u00e4)ufig E-Mails von[^\n]*/gi, ' ');
  t = t.replace(/Erfahren Sie, warum dies wichtig ist[^\n]*/gi, ' ');
  t = t.replace(/https?:\/\/\S*(safelinks\.protection\.outlook\.com|atpscan\.global\.hornetsecurity\.com|aka\.ms\/LearnAboutSenderIdentification)\S*/gi, ' ');
  t = t.replace(/https?:\/\/\S{180,}/g, ' ');
  t = t.replace(/Diese E-Mail enth(a|ae|\u00e4)lt die Referenz-ID[\s\S]*$/i, ' ');
  t = t.replace(/(^|\n)[ \t]*\*?Von:\*?[ \t][\s\S]*$/i, '\n');
  t = t.replace(/(^|\n)[ \t]*-{3,}[ \t]*Urspr(u|ue|\u00fc)ngliche Nachricht[ \t]*-{3,}[\s\S]*$/i, '\n');
  t = t.replace(/RWG Rheinland eG[ \t]*\|[\s\S]*$/i, ' ');
  t = t.replace(/(^|\n)[ \t]*(Vorstand|Aufsichtsrat|Hauptamtlich)[ \t]*:[^\n]*/gi, '$1');
  t = t.replace(ABBINDER, '$1');
  t = t.replace(/(^|\n)[ \t]*(Telefon|Mobil|Fax|E-Mail|Website|Dienstsitz)[ \t]*:[^\n]*/gi, '$1');
  t = t.replace(/\+?\d[\d \t()\/\\-]{8,}\d/g, ' ');
  t = t.replace(/\\{2,}/g, ' ');
  t = t.replace(/\|+/g, ' ');
  t = t.replace(/[ \t]{2,}/g, ' ');
  t = t.replace(/\n{3,}/g, '\n\n');
  return t.trim();
}

// Zaehlt nur Buchstaben und Ziffern ausserhalb von URLs. Ein Chunk aus
// Trennzeichen, Links und Leerraum hat damit Substanz 0.
function substanz(text) {
  return String(text || '')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/[^\p{L}\p{N}]+/gu, '')
    .length;
}

function istBrauchbar(text) {
  const clean = String(text || '');
  if (AUTOREPLY.test(clean)) return false;
  return substanz(clean) >= MIN_SUBSTANZ;
}

function estimateTokens(text) {
  return Math.ceil(String(text || '').length / 4);
}

// ============================================================
// UTF-16 SICHERHEIT
// Emojis bestehen aus einem Surrogate-Paar (zwei Code-Units). Faellt eine
// Schnittkante zwischen beide Haelften, entsteht ein verwaistes Surrogate.
// Postgres/PostgREST lehnt den kompletten Batch dann mit PGRST102
// ("Empty or invalid json") ab. Zwei Schutzebenen:
//   1) surrogatSichererIndex - es wird nie mitten durch ein Paar geschnitten
//   2) entferneEinzelneSurrogate - verwaiste Haelften werden vor dem Schreiben
//      entfernt, egal woher sie stammen
// ============================================================
function entferneEinzelneSurrogate(text) {
  const s = String(text || '');
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = i + 1 < s.length ? s.charCodeAt(i + 1) : 0;
      if (next >= 0xdc00 && next <= 0xdfff) {
        out += s[i] + s[i + 1];
        i++;
      }
      continue;
    }
    if (code >= 0xdc00 && code <= 0xdfff) continue;
    out += s[i];
  }
  return out;
}

function surrogatSichererIndex(text, index) {
  if (index <= 0 || index >= text.length) return index;
  const prev = text.charCodeAt(index - 1);
  const cur = text.charCodeAt(index);
  if (prev >= 0xd800 && prev <= 0xdbff && cur >= 0xdc00 && cur <= 0xdfff) return index + 1;
  return index;
}

function saeubereWerte(wert) {
  if (typeof wert === 'string') return entferneEinzelneSurrogate(wert);
  if (Array.isArray(wert)) return wert.map(saeubereWerte);
  if (wert && typeof wert === 'object') {
    const out = {};
    for (const key of Object.keys(wert)) out[key] = saeubereWerte(wert[key]);
    return out;
  }
  return wert;
}

function findBoundary(text, start, idealEnd) {
  if (idealEnd >= text.length) return text.length;
  const minimumEnd = Math.min(text.length, start + Math.floor(CHUNK_SIZE * 0.65));
  const search = text.slice(minimumEnd, idealEnd);
  const candidates = [
    search.lastIndexOf('\n\n'),
    search.lastIndexOf('\n'),
    search.lastIndexOf('. '),
    search.lastIndexOf('; '),
    search.lastIndexOf(', '),
    search.lastIndexOf(' '),
  ].filter((index) => index >= 0);
  if (!candidates.length) return idealEnd;
  return minimumEnd + Math.max(...candidates) + 1;
}

function splitText(text, maxChars = CHUNK_SIZE, overlap = OVERLAP) {
  const normalized = String(text || '').trim();
  if (!normalized) return [];
  const parts = [];
  let start = 0;
  while (start < normalized.length) {
    const idealEnd = Math.min(start + maxChars, normalized.length);
    const end = surrogatSichererIndex(normalized, findBoundary(normalized, start, idealEnd));
    const part = normalized.slice(start, end).trim();
    if (part) parts.push(part);
    if (end >= normalized.length) break;
    const nextStart = surrogatSichererIndex(normalized, Math.max(0, end - overlap));
    start = nextStart <= start ? end : nextStart;
  }
  return parts;
}

const publicComments = (n.comments || []).filter((c) => !isAgentComment(c));
const internalComments = (n.internal_comments || []).filter((c) => !isAgentComment(c));
const agentCommentCount =
  ((n.comments || []).length + (n.internal_comments || []).length) -
  (publicComments.length + internalComments.length);

const attachments = n.attachments || [];
const isResolved = Boolean(n.jira_resolved_at) || Boolean(n.resolution);

const baseMetadata = {
  source_type: 'jira',
  source_ref: n.issue_key,
  title: n.summary,
  url: `${JIRA_BASE}/browse/${n.issue_key}`,
  updated_at: n.updated_at,
  content_hash: n.content_hash,
  rag_flow_version: FLOW_VERSION,
  noise_filter: NOISE_FILTER,
  audience: AUDIENCE,
  ticket_key: n.issue_key,
  summary: n.summary,
  status: n.status,
  resolution: n.resolution,
  is_resolved: isResolved,
  priority: n.priority,
  issue_type: n.issue_type,
  project_key: n.project_key,
  request_type: n.request_type,
  labels: n.labels || [],
  components: n.components || [],
  created_at: n.created_at,
  resolved_at: n.jira_resolved_at,
};

const sourceId = row.id;
let chunkIndex = 0;
const chunks = [];
let verworfen = 0;

function pushChunk(text, metadata, audience) {
  const clean = entferneEinzelneSurrogate(text).trim();
  if (!clean) return;

  const chunkType = metadata?.chunk_type;
  if (!ALLOWED_CHUNK_TYPES.includes(chunkType)) {
    throw new Error('INVALID_CHUNK_TYPE: ' + String(chunkType));
  }

  // Der Header traegt die Ticket-Identitaet und wird nie verworfen.
  if (chunkType !== 'header' && !istBrauchbar(clean)) {
    verworfen++;
    return;
  }

  const chunkAudience = audience || AUDIENCE;

  chunks.push({
    source_id: sourceId,
    source_type: 'jira',
    source_ref: n.issue_key,
    audience: chunkAudience,
    chunk_index: chunkIndex++,
    chunk_text: clean,
    token_count: estimateTokens(clean),
    metadata: saeubereWerte({ ...baseMetadata, ...metadata, audience: chunkAudience }),
  });
}

// ---------- HEADER ----------
const header = [
  `[${n.issue_key}] ${n.summary || ''}`.trim(),
  n.kategorie ? `Kategorie: ${n.kategorie}` : '',
  n.status ? `Status: ${n.status}` : '',
  n.resolution ? `Resolution: ${n.resolution}` : '',
  `Geloest: ${isResolved ? 'ja' : 'nein'}`,
  n.priority ? `Prioritaet: ${n.priority}` : '',
  n.issue_type ? `Typ: ${n.issue_type}` : '',
  n.project_key ? `Projekt: ${n.project_key}` : '',
  n.request_type ? `Request Type: ${n.request_type}` : '',
  n.assignee_name ? `Zustaendig: ${n.assignee_name}` : '',
  n.reporter_name ? `Reporter: ${n.reporter_name}` : '',
  n.parent_key ? `Parent: ${n.parent_key}` : '',
  n.epic_link ? `Epic: ${n.epic_link}` : '',
  (n.labels || []).length ? `Labels: ${n.labels.join(', ')}` : '',
  (n.components || []).length ? `Komponenten: ${n.components.join(', ')}` : '',
  (n.linked_tickets || []).length
    ? `Verknuepfte Tickets: ${n.linked_tickets.map((l) => `${l.key} (${l.type})`).join(', ')}`
    : '',
  (n.mentioned_issue_keys || []).length
    ? `Erwaehnte Tickets: ${n.mentioned_issue_keys.join(', ')}`
    : '',
  attachments.length
    ? `Anhaenge: ${attachments.map((a) => a.filename || 'unbekannt').join(', ')}`
    : '',
  n.created_at ? `Created: ${n.created_at}` : '',
  n.updated_at ? `Updated: ${n.updated_at}` : '',
  n.jira_resolved_at ? `Resolved: ${n.jira_resolved_at}` : '',
  `URL: ${JIRA_BASE}/browse/${n.issue_key}`,
]
  .filter(Boolean)
  .join('\n');

pushChunk(header, {
  chunk_type: 'header',
  attachment_count: attachments.length,
  comment_count: publicComments.length,
  internal_comment_count: internalComments.length,
  agent_comment_count: agentCommentCount,
  jsd_flag_available: n.jsd_flag_available === true,
});

// ---------- BESCHREIBUNG ----------
const beschreibung = bereinige(n.description || '');
if (beschreibung && istBrauchbar(beschreibung)) {
  const descriptionParts = splitText(`Beschreibung:\n${beschreibung}`, CHUNK_SIZE, OVERLAP);
  for (let index = 0; index < descriptionParts.length; index++) {
    pushChunk(descriptionParts[index], {
      chunk_type: 'content',
      content_origin: 'description',
      part: index + 1,
    });
  }
} else if (n.description) {
  verworfen++;
}

// ---------- KOMMENTARE ----------
function kommentarChunks(comment, istIntern) {
  const body = bereinige(comment.body || '');
  if (!body || !istBrauchbar(body)) {
    verworfen++;
    return;
  }

  const prefix =
    [
      `Kommentar von ${comment.author_name || 'Unbekannt'}`,
      istIntern ? 'intern' : '',
      comment.created_at ? `Datum: ${comment.created_at}` : '',
      comment.updated_at && comment.updated_at !== comment.created_at
        ? `Aktualisiert: ${comment.updated_at}`
        : '',
    ]
      .filter(Boolean)
      .join(' | ') + ':\n';

  const availableChars = Math.max(600, CHUNK_SIZE - prefix.length - 60);
  const parts = splitText(body, availableChars, OVERLAP);

  for (let partNo = 0; partNo < parts.length; partNo++) {
    const text =
      prefix + (parts.length > 1 ? `(Teil ${partNo + 1}/${parts.length})\n` : '') + parts[partNo];

    pushChunk(
      text,
      {
        chunk_type: 'comment',
        comment_id: comment.id,
        comment_author: comment.author_name,
        comment_date: comment.created_at,
        is_internal_comment: istIntern,
        part: partNo + 1,
      },
      audienceFuer(istIntern)
    );
  }
}

for (const comment of publicComments) kommentarChunks(comment, false);
for (const comment of internalComments) kommentarChunks(comment, true);

if (!chunks.length) {
  throw new Error('NO_TEXT_CHUNKS_CREATED');
}

// Der Zaehler gehoert in die Metadaten des Headers, nicht in die Chunk-Zeile:
// document_chunks hat keine Spalte dafuer.
chunks[0].metadata.verworfene_chunks = verworfen;

return chunks.map((chunk) => ({ json: chunk }));

