if (!Array.isArray(data)) {
  throw new Error('TEXT_EMBEDDING_RESPONSE_DATA_MISSING');
}

if (data.length !== chunks.length) {
  throw new Error(
    `TEXT_EMBEDDING_COUNT_MISMATCH: expected=${chunks.length}, actual=${data.length}`
  );
}

const embeddingByIndex = new Map();

for (const entry of data) {
  if (
    Number.isInteger(entry?.index) &&
    Array.isArray(entry?.embedding)
  ) {
    embeddingByIndex.set(entry.index, entry.embedding);
  }
}

const rows = chunks.map((chunk, index) => {
  const embedding =
    embeddingByIndex.get(index) ||
    data[index]?.embedding ||
    null;

  if (!Array.isArray(embedding)) {
    throw new Error(`TEXT_EMBEDDING_MISSING_AT_INDEX_${index}`);
  }

  if (embedding.length !== 1536) {
    throw new Error(
      `TEXT_EMBEDDING_DIMENSION_MISMATCH_AT_${index}: ${embedding.length}`
    );
  }

  return {
    ...chunk,
    embedding: '[' + embedding.join(',') + ']',
  };
});

return [{
  json: {
    rows,
    text_chunk_count: rows.length,
  }
}];

const n = $('Normalize Issue').first().json;
const ticketRow = $('Get Ticket Row').first().json;

if (!ticketRow?.id) {
  throw new Error('MISSING_TICKET_ID_FOR_IMAGES');
}

const AUDIENCE =
  typeof ticketRow.audience === 'string' && ticketRow.audience.trim()
    ? ticketRow.audience.trim()
    : null;

if (!AUDIENCE) {
  throw new Error('MISSING_TICKET_AUDIENCE: ' + n.issue_key);
}

// ============================================================
// AUDIENCE JE BILD STATT PAUSCHAL JE TICKET
//
// Bisher erbte JEDER Bildchunk die Ticket-Audience. Bilder aus
// internen Kommentaren waren dadurch fuer den Fachbereich sichtbar.
// Messung 23.08.2026: 1362 Bildchunks aus 673 Tickets, davon 192
// Tickets mit E-Mail-Adressen und 100 Chunks mit Rufnummern im
// OCR-Text - alle public.
//
// WARUM AUTOR + ZEIT UND KEIN ID-JOIN
// Jira liefert am Anhang keine Kommentar-Referenz. Die Media-IDs im
// Kommentartext sind Media-Services-UUIDs, die Attachment-IDs sind
// numerisch - ein Join ueber IDs ist nicht moeglich (geprueft an
// SSD-7932 und SSD-5878, null Uebereinstimmungen).
// Belastbar ist der Schreibvorgang: Anhang und Kommentar entstehen
// gemeinsam. Messung an denselben Tickets: 39 von 42 Anhaengen
// eindeutig zuordenbar, Abstand durchgehend 0-1 Sekunden. Das
// Fenster ist deshalb eng - es soll denselben Schreibvorgang
// erfassen, nicht raten.
//
// Rohdaten kommen bewusst aus Get Issue und Get Comments statt aus
// Normalize Issue: dort werden Autor und Zeitstempel der Anhaenge
// nicht mitgefuehrt. Beide Nodes liegen im selben Pfad und laufen
// immer, bevor dieser Node ausgefuehrt wird.
//
// FAIL CLOSED: Herabstufen ist erlaubt, Heraufstufen nie. Ein Bild
// kann nie oeffentlicher werden als sein Ticket.
// ============================================================
const HERKUNFT_FENSTER_MS = 60000;

const rohIssue = $('Get Issue').first().json || {};
const rohFields = rohIssue.fields || {};
const reporterId = rohFields.reporter?.accountId || null;

const rohKommentare = $('Get Comments').all()
  .map((eintrag) => eintrag.json || {})
  .filter((kommentar) => Object.keys(kommentar).length > 0);

// Gleiche Fail-Closed-Logik wie in Normalize Issue: fehlt das Flag
// vollstaendig, gilt die Sichtbarkeit als unbekannt und damit intern.
const jsdFlagVerfuegbar = rohKommentare.some((kommentar) =>
  Object.prototype.hasOwnProperty.call(kommentar, 'jsdPublic')
);

const anhangNachId = new Map();
for (const anhang of (Array.isArray(rohFields.attachment) ? rohFields.attachment : [])) {
  if (anhang && anhang.id !== undefined && anhang.id !== null) {
    anhangNachId.set(String(anhang.id), anhang);
  }
}

function ermittleHerkunft(attachmentId) {
  const anhang = anhangNachId.get(String(attachmentId));
  const autorId = anhang?.author?.accountId || null;
  const zeit = Date.parse(anhang?.created || '');

  if (autorId && !Number.isNaN(zeit)) {
    let treffer = null;
    for (const kommentar of rohKommentare) {
      if ((kommentar.author?.accountId || null) !== autorId) continue;
      const kommentarZeit = Date.parse(kommentar.created || '');
      if (Number.isNaN(kommentarZeit)) continue;
      const abstand = Math.abs(kommentarZeit - zeit);
      if (abstand > HERKUNFT_FENSTER_MS) continue;
      if (!treffer || abstand < treffer.abstand) {
        treffer = { abstand, kommentar };
      }
    }
    if (treffer) {
      const istOeffentlich = jsdFlagVerfuegbar
        ? treffer.kommentar.jsdPublic === true
        : false;
      return {
        herkunft: 'kommentar',
        quell_kommentar_id: treffer.kommentar.id ? String(treffer.kommentar.id) : null,
        jsd_public: istOeffentlich,
        herkunft_abstand_ms: treffer.abstand,
        audience: istOeffentlich ? AUDIENCE : 'it_internal',
      };
    }
  }

  // Kein Kommentartreffer, aber der Reporter hat den Anhang erzeugt:
  // dann kam er mit der Anfrage selbst und ist fuer ihn sichtbar.
  if (autorId && reporterId && autorId === reporterId) {
    return {
      herkunft: 'anfrage',
      quell_kommentar_id: null,
      jsd_public: true,
      herkunft_abstand_ms: null,
      audience: AUDIENCE,
    };
  }

  return {
    herkunft: 'unbekannt',
    quell_kommentar_id: null,
    jsd_public: false,
    herkunft_abstand_ms: null,
    audience: 'it_internal',
  };
}

const IMAGE_INDEX_BASE = 100000;
const VISION_MODEL = 'gpt-4.1-mini-2025-04-14';

function cleanBaseName(filename, fallback) {
  const value = String(filename || fallback || 'jira_image')
    .replace(/\.[^.]+$/, '')
    .replace(/[^a-zA-Z0-9._-]/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '');

  return (value || fallback || 'jira_image').slice(0, 120);
}

const images = (n.bilder || []).map((image, index) => {
  const attachmentId = String(image.attachment_id || index);
  const baseName = cleanBaseName(
    image.filename,
    `jira_image_${attachmentId}`
  );

  const storage_key =
    `JIRA/${n.issue_key}/${attachmentId}_${baseName}.jpg`;

  const herkunft = ermittleHerkunft(attachmentId);

  return {
    source_id: ticketRow.id,
    issue_key: n.issue_key,
    audience: herkunft.audience,
    herkunft: herkunft.herkunft,
    quell_kommentar_id: herkunft.quell_kommentar_id,
    jsd_public: herkunft.jsd_public,
    attachmentId,
    download_url: image.download_url,
    thumbnail_url: image.thumbnail_url || null,
    original_filename:
      image.filename || `jira_image_${attachmentId}`,
    original_mime_type:
      image.mime_type || 'application/octet-stream',
    original_size: image.size ?? null,
    storage_key,
    image_chunk_index: IMAGE_INDEX_BASE + index,
    vision_model: VISION_MODEL,
  };
});

return [{
  json: {
    images,
    image_count: images.length,
    bilder_it_internal: images.filter((bild) => bild.audience === 'it_internal').length,
    bilder_herkunft_unbekannt: images.filter((bild) => bild.herkunft === 'unbekannt').length,
    jsd_flag_verfuegbar: jsdFlagVerfuegbar,
    expected_storage_keys: images.map((image) => image.storage_key),
    expected_image_chunk_indices: images.map(
      (image) => image.image_chunk_index
    ),
    vision_model: VISION_MODEL,
  }
}];

