      summary: n.summary,
      status: n.status,
      resolution: n.resolution,
      is_resolved: true,
      resolved_at: n.jira_resolved_at,
      loesung_schluessel: loesungSchluessel,
      solution_prompt_version: SOLUTION_PROMPT_VERSION,
    };

    const unveraendert =
      bestand.audience === AUDIENCE &&
      stabil(neueMetadata) === stabil(bestand.metadata);

    if (unveraendert) {
      aktion = 'keine';
      cache_grund = 'treffer_ohne_delta';
    } else {
      aktion = 'patch';
      cache_grund = 'treffer';
      patch_body = {
        audience: AUDIENCE,
        metadata: neueMetadata,
      };
    }
  }
}

return [{
  json: {
    source_id: ticket.id,
    issue_key: n.issue_key,
    chunk_index: chunkIndex,
    loesung_schluessel: loesungSchluessel,
    solution_prompt_version: SOLUTION_PROMPT_VERSION,
    aktion,
    cache_grund,
    patch_body,
    loesung_llm_gespart: aktion === 'analyse' ? 0 : 1,
  },
}];
